package com.apexstreet.controller;
import com.apexstreet.dto.*; import com.apexstreet.service.AutomationService; import com.apexstreet.service.AutomationScheduler; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/automation")
public class AutomationController { private final AutomationService service; private final AutomationScheduler scheduler; public AutomationController(AutomationService s, AutomationScheduler scheduler){service=s;this.scheduler=scheduler;}
 @PostMapping("/run-now") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<Void> runNow(@RequestParam Long areaId,@RequestParam com.apexstreet.model.AutomationWeekType weekType){scheduler.runNow(areaId,weekType); return ResponseEntity.noContent().build();}
 @GetMapping("/areas") public List<AutomationResponses.AreaSummary> areas(){return service.summaries();}
 @GetMapping("/areas/{areaId}") public AutomationResponses.Page page(@PathVariable Long areaId){return service.page(areaId);}
 @PutMapping("/areas/{areaId}/configuration") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page config(@PathVariable Long areaId,@Valid @RequestBody AutomationRequests.ConfigurationRequest r){return service.updateConfig(areaId,r);}
 @PostMapping("/areas/{areaId}/phases") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page phase(@PathVariable Long areaId,@Valid @RequestBody AutomationRequests.PhaseRequest r){return service.createPhase(areaId,r);}
 @PutMapping("/areas/{areaId}/phases/{phaseId}") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page phase(@PathVariable Long areaId,@PathVariable Long phaseId,@Valid @RequestBody AutomationRequests.PhaseRequest r){return service.updatePhase(areaId,phaseId,r);}
 @DeleteMapping("/areas/{areaId}/phases/{phaseId}") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page phase(@PathVariable Long areaId,@PathVariable Long phaseId){return service.deletePhase(areaId,phaseId);}
 @PutMapping("/areas/{areaId}/lights/{lightId}/override") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page override(@PathVariable Long areaId,@PathVariable String lightId,@Valid @RequestBody AutomationRequests.OverrideRequest r){return service.override(areaId,lightId,r);}
 @PostMapping("/areas/{areaId}/group-command") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page group(@PathVariable Long areaId,@Valid @RequestBody AutomationRequests.GroupCommandRequest r){return service.group(areaId,r);}
 @PostMapping("/areas/{areaId}/return-to-schedule") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page schedule(@PathVariable Long areaId){return service.returnToSchedule(areaId);}
 @DeleteMapping("/areas/{areaId}/lights/{lightId}/override") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page clearOverride(@PathVariable Long areaId,@PathVariable String lightId){return service.clearOverride(areaId,lightId);}
 @PostMapping("/areas/{areaId}/events") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page event(@PathVariable Long areaId,@Valid @RequestBody AutomationRequests.EventRequest r){return service.createEvent(areaId,r);}
 @PutMapping("/areas/{areaId}/events/{eventId}") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page event(@PathVariable Long areaId,@PathVariable Long eventId,@Valid @RequestBody AutomationRequests.EventRequest r){return service.updateEvent(areaId,eventId,r);}
 @DeleteMapping("/areas/{areaId}/events/{eventId}") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public AutomationResponses.Page event(@PathVariable Long areaId,@PathVariable Long eventId){return service.deleteEvent(areaId,eventId);}
}
